import { writeFileSync } from "fs";
import { fetch } from "undici";

const DIR = import.meta.dirname;

function getEnv(key) {
    let value = process.env[key];
    if (value === undefined) {
        throw new Error(`Key "${key}" does not exist`);
    }
    return value;
}

let configJson = ""
let pfpUrl = ""

if (process.argv[2] === "--dev") {
    configJson = `{
    "nickname": "John Pork",
    "description": "Oink oink",
    "bio": "27 y/o, susgender (like sus as in pig), pansexual. I love laughing and Friday racing",
    "color": "#600afe",
    "canonicalUrl": "https://example.com/",
    "locale": "en_US",
    "theme": "default",
    "links": [
        {
            "label": "Example",
            "href": "https://example.com",
            "icon": "siGithub"
        }
    ]
}`
    pfpUrl = "data:image/png;base64,"
} else {
    configJson = getEnv("SLOPTREE_CONFIG");
    pfpUrl = getEnv("SLOPTREE_PFP");
}

writeFileSync(DIR + "/../src/configuration/data.json", configJson);

let resp = await fetch(pfpUrl);

const CONTENT_TYPE_MAP = {
    "image/jpeg": ".jpg",
    "image/png": ".png",
    "image/gif": ".gif",
    "image/webp": ".webp",
    "image/svg+xml": ".svg",
    "image/bmp": ".bmp"
}

let contentType = resp.headers.get("content-type");
let extension = CONTENT_TYPE_MAP[contentType];
if (extension === undefined) {
    throw new Error(`Unknown file type "${contentType}" for SLOPTREE_PFP`)
}

let data = await resp.bytes();
writeFileSync(DIR + "/../src/configuration/pfp" + extension, data);